
def revenue_by_product(df):
    """Calculate total revenue generated by each product."""

    result = df.groupby("Product")["Revenue"].sum()

    return result.sort_values(ascending=False)


def units_sold_by_product(df):
    """Calculate total units sold for each product."""

    result = df.groupby("Product")["Quantity"].sum()

    return result.sort_values(ascending=False)


def revenue_by_category(df):
    """Calculate total revenue generated by each category."""

    result = df.groupby("Category")["Revenue"].sum()

    return result.sort_values(ascending=False)

